const serverless = require('@vendia/serverless-express');
const express = require('express');
const { PrismaClient } = require('@prisma/client');

const prisma = new PrismaClient();
const app = express();
app.use(express.json());

app.put('/api/tenants/:orgId/sso', async (req, res) => {
  const callerSub = req.headers['x-authorizer-principal-id'];
  const callerTenantId = req.headers['x-authorizer-tenant-id'];
  const callerRole = req.headers['x-authorizer-role'];
  const { ssoMetadataUrl, enforceSso } = req.body;

  if (callerTenantId !== req.params.orgId || callerRole !== 'SUPER_ADMIN') {
    return res.status(403).json({ error: 'Forbidden: unauthorized to update SSO configuration for this organization' });
  }

  const ssoConfig = await prisma.ssoConfiguration.upsert({
    where: { organizationId: req.params.orgId },
    update: { metadataUrl: ssoMetadataUrl, isEnforced: enforceSso },
    create: { organizationId: req.params.orgId, metadataUrl: ssoMetadataUrl, isEnforced: enforceSso }
  });

  res.json({ success: true, orgId: req.params.orgId, ssoConfig });
});

exports.handler = serverless({ app });
